def largest_prime_factor(n: int) -> int:
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    largest_factor = -1
    while n > 1:
        for i in range(2, n):
            if n % i == 0 and is_prime(i):
                largest_factor = i
                n = n // i
                break
        if n == 1:
            break
    return largest_factor
